SET IDENTITY_INSERT NhanVien OFF;
INSERT INTO TaiKhoan (TenDangNhap, MatKhau, MaNhanVien, MaDocGia, MaVaiTro, TrangThai)
SELECT
    N'nv' + RIGHT(N'000' + CONVERT(NVARCHAR(3), MaNhanVien), 3),
    N'123456',
    MaNhanVien,
    NULL,
    CASE WHEN MaNhanVien = 1 THEN 1 ELSE 2 END,
    1
FROM NhanVien
ORDER BY MaNhanVien;

INSERT INTO TaiKhoan (TenDangNhap, MatKhau, MaNhanVien, MaDocGia, MaVaiTro, TrangThai)
SELECT
    N'dg' + RIGHT(N'000' + CONVERT(NVARCHAR(3), MaDocGia), 3),
    N'123456',
    NULL,
    MaDocGia,
    4,
    1
FROM DocGia
ORDER BY MaDocGia;

