DECLARE @i INT=1;
WHILE @i<=120 BEGIN INSERT PhieuNhap(MaNCC,MaNhanVien,NgayNhap,TongTien,GhiChu) VALUES(1+@i%25,1+@i%10,DATEADD(DAY,-@i*4,'2026-07-25'),0,N'Nhập bổ sung kho'); SET @i+=1; END;
SET @i=1; WHILE @i<=400 BEGIN DECLARE @pn INT=1+(@i-1)%120,@s INT=1+(@i*17)%310,@sl INT=1+@i%4; DECLARE @dg DECIMAL(18,2)=45000+(@s*9000)%180000; INSERT ChiTietNhap(MaPhieuNhap,MaSach,SoLuong,DonGia) VALUES(@pn,@s,@sl,@dg); SET @i+=1; END;
UPDATE p SET TongTien=x.T FROM PhieuNhap p CROSS APPLY(SELECT SUM(ThanhTien) T FROM ChiTietNhap WHERE MaPhieuNhap=p.MaPhieuNhap)x;
DISABLE TRIGGER TRG_ChiTietMuon_KiemTraNghiepVu ON ChiTietMuon; DISABLE TRIGGER TRG_ChiTietTra_CapNhatTrangThai ON ChiTietTra;
SET @i=1; WHILE @i<=400 BEGIN INSERT PhieuMuon(MaThe,MaNhanVien,NgayMuon,HanTra,TrangThai) VALUES(1+(@i*17)%100,1+@i%10,DATEADD(DAY,-500+@i,'2026-07-25'),DATEADD(DAY,-486+@i,'2026-07-25'),CASE WHEN @i<=320 THEN N'Đã trả' WHEN @i<=386 THEN N'Quá hạn' ELSE N'Đang mượn' END); SET @i+=1; END;
SET @i=1; WHILE @i<=600 BEGIN DECLARE @pm INT=CASE WHEN @i<=480 THEN CEILING(@i*2/3.0) ELSE 320+CEILING((@i-480)*2/3.0) END; INSERT ChiTietMuon(MaPhieuMuon,MaCuonSach,TrangThai) VALUES(@pm,CASE WHEN @i<=480 THEN 1+(@i*7)%560 ELSE @i+100 END,CASE WHEN @pm<=320 THEN N'Đã trả' WHEN @pm<=386 THEN N'Quá hạn' ELSE N'Đang mượn' END); SET @i+=1; END;
SET @i=1; WHILE @i<=320 BEGIN INSERT PhieuTra(MaPhieuMuon,MaNhanVien,NgayTra,GhiChu) VALUES(@i,1+@i%10,DATEADD(DAY,-470+@i,'2026-07-25'),N'Đã kiểm tra sách'); SET @i+=1; END;
SET @i=1; WHILE @i<=480 BEGIN DECLARE @pt INT=CEILING(@i*2/3.0); INSERT ChiTietTra(MaPhieuTra,MaChiTietMuon,TinhTrangTra,SoNgayTre) VALUES(@pt,@i,CASE WHEN @i%31=0 THEN N'Hư hỏng' WHEN @i%13=0 THEN N'Rách nhẹ' ELSE N'Tốt' END,CASE WHEN @i%5=0 THEN @i%18 ELSE 0 END); SET @i+=1; END;
UPDATE ctm
SET ctm.TrangThai = CASE WHEN ctt.TinhTrangTra = N'Mất' THEN N'Mất' WHEN ctt.TinhTrangTra IN (N'Rách nhẹ', N'Hư hỏng') THEN N'Hỏng' ELSE N'Đã trả' END
FROM ChiTietMuon ctm
JOIN ChiTietTra ctt ON ctt.MaChiTietMuon = ctm.MaChiTietMuon;
;WITH LanTraMoiNhat AS (
    SELECT ctm.MaCuonSach, ctt.TinhTrangTra,
           ROW_NUMBER() OVER (PARTITION BY ctm.MaCuonSach ORDER BY ctm.MaChiTietMuon DESC) AS rn
    FROM ChiTietMuon ctm
    JOIN ChiTietTra ctt ON ctt.MaChiTietMuon = ctm.MaChiTietMuon
)
UPDATE cs
SET cs.TinhTrang = x.TinhTrangTra,
    cs.TrangThai = CASE WHEN x.TinhTrangTra = N'Mất' THEN N'Mất' WHEN x.TinhTrangTra IN (N'Rách nhẹ', N'Hư hỏng') THEN N'Hỏng' ELSE N'Có sẵn' END
FROM CuonSach cs
JOIN LanTraMoiNhat x ON x.MaCuonSach = cs.MaCuonSach AND x.rn = 1;
UPDATE cs SET TrangThai=N'Đang mượn' FROM CuonSach cs JOIN ChiTietMuon c ON c.MaCuonSach=cs.MaCuonSach WHERE c.TrangThai IN(N'Đang mượn',N'Quá hạn');
ENABLE TRIGGER TRG_ChiTietMuon_KiemTraNghiepVu ON ChiTietMuon;
ENABLE TRIGGER TRG_ChiTietTra_CapNhatTrangThai ON ChiTietTra;
SET @i=1; WHILE @i<=100 BEGIN INSERT PhieuPhat(MaDocGia,MaPhieuMuon,MaNhanVien,NgayLap,TongTien,TrangThai) VALUES(1+(@i*17)%100,@i,1+@i%10,DATEADD(DAY,-@i,'2026-07-25'),5000*(1+@i%12),CASE WHEN @i%4=0 THEN N'Chưa thanh toán' ELSE N'Đã thanh toán' END); INSERT ChiTietPhat(MaPhieuPhat,MaChiTietMuon,LoaiPhat,NoiDung,SoNgayTre,SoTien) VALUES(@i,@i,N'Trễ hạn',N'Phạt trả sách trễ',1+@i%12,5000*(1+@i%12)); SET @i+=1; END;
SET @i=1; WHILE @i<=150 BEGIN INSERT DatTruocSach(MaDocGia,MaSach,NgayDat,HanGiuDen,TrangThai) VALUES(1+(@i-1)%100,1+(@i*19)%310,DATEADD(HOUR,-@i*7,'2026-07-25'),DATEADD(HOUR,-@i*7+72,'2026-07-25'),CHOOSE(1+@i%5,N'Đang chờ',N'Đã thông báo',N'Đã nhận',N'Đã hủy',N'Hết hạn')); SET @i+=1; END;
SET @i=1; WHILE @i<=650 BEGIN INSERT DanhGiaSach(MaSach,MaDocGia,SoSao,NhanXet,NgayDanhGia,TrangThai) VALUES(1+(@i*37+FLOOR((@i-1)/100.0)*11)%310,1+(@i-1)%100,3+@i%3,N'Sách hữu ích cho học tập và nghiên cứu.',DATEADD(HOUR,-@i*19,'2026-07-25'),1); SET @i+=1; END;
SET @i=1;
WHILE @i<=700
BEGIN
 DECLARE @LoaiTB INT=1+@i%5,@BienTheTB INT=@i%4,@MaDocGiaTB INT=CASE WHEN @i%12=0 THEN NULL ELSE 1+(@i*13)%100 END,@MaNhanVienTB INT=CASE WHEN @i%12=0 THEN 1+@i%10 ELSE NULL END;
 DECLARE @TenNguoiNhanTB NVARCHAR(150)=COALESCE((SELECT HoTen FROM DocGia WHERE MaDocGia=@MaDocGiaTB),(SELECT HoTen FROM NhanVien WHERE MaNhanVien=@MaNhanVienTB),N'bạn');
 DECLARE @TenSachTB NVARCHAR(200)=(SELECT TenSach FROM Sach WHERE MaSach=1+(@i*37)%310);
 DECLARE @TieuDeTB NVARCHAR(200)=CASE @LoaiTB
  WHEN 1 THEN CHOOSE(@BienTheTB+1,N'Nhắc trả sách đúng hạn',N'Cảnh báo sách đang quá hạn',N'Phí phạt quá hạn dự kiến',N'Xác nhận tiếp nhận sách trả muộn')
  WHEN 2 THEN CHOOSE(@BienTheTB+1,N'Thẻ thư viện sắp hết hạn',N'Xác nhận phí thường niên',N'Hồ sơ độc giả đã được cập nhật',N'Chào mừng bạn đến Thư viện EPU')
  WHEN 3 THEN CHOOSE(@BienTheTB+1,N'Sách mới đã có tại thư viện',N'Giáo trình mới dành cho bạn',N'Gợi ý tài liệu học tập',N'Khám phá sách mới trong tuần')
  WHEN 4 THEN CHOOSE(@BienTheTB+1,N'Thông báo lịch phục vụ',N'Bảo trì hệ thống thư viện',N'Nhắc nhở nội quy phòng đọc',N'Sự kiện đọc sách tại EPU')
  ELSE CHOOSE(@BienTheTB+1,N'Đặt trước sách thành công',N'Sách đặt trước đã sẵn sàng',N'Sắp hết hạn giữ sách',N'Cập nhật yêu cầu đặt trước') END;
 DECLARE @NoiDungTB NVARCHAR(MAX)=CASE @LoaiTB
  WHEN 1 THEN CONCAT(N'Kính gửi ',@TenNguoiNhanTB,N', vui lòng kiểm tra thời hạn trả cuốn “',@TenSachTB,N'”. Mã nhắc #',FORMAT(@i,N'0000'),N'; liên hệ quầy thủ thư nếu cần gia hạn.')
  WHEN 2 THEN CONCAT(N'Kính gửi ',@TenNguoiNhanTB,N', thông tin thẻ và hồ sơ thư viện của bạn vừa được hệ thống rà soát. Mã giao dịch #',FORMAT(@i,N'0000'),N'.')
  WHEN 3 THEN CONCAT(N'Thư viện EPU giới thiệu “',@TenSachTB,N'”. ',@TenNguoiNhanTB,N' có thể tra cứu vị trí và tình trạng cuốn sách trên hệ thống. Mã giới thiệu #',FORMAT(@i,N'0000'),N'.')
  WHEN 4 THEN CONCAT(N'Kính gửi ',@TenNguoiNhanTB,N', Thư viện EPU gửi thông tin hoạt động và dịch vụ kỳ này. Vui lòng theo dõi lịch tại quầy hoặc trên hệ thống. Mã thông báo #',FORMAT(@i,N'0000'),N'.')
  ELSE CONCAT(N'Kính gửi ',@TenNguoiNhanTB,N', yêu cầu đặt trước cuốn “',@TenSachTB,N'” đã được cập nhật. Vui lòng nhận sách đúng thời hạn. Mã đặt trước #',FORMAT(@i,N'0000'),N'.') END;
 INSERT ThongBao(MaLoaiThongBao,MaDocGia,MaNhanVien,TieuDe,NoiDung,NgayGui,DaDoc)
 VALUES(@LoaiTB,@MaDocGiaTB,@MaNhanVienTB,@TieuDeTB,@NoiDungTB,DATEADD(HOUR,-@i*5,'2026-07-25'),CASE WHEN @i%3=0 THEN 0 ELSE 1 END);
 INSERT NhatKyHeThong(MaTaiKhoan,HanhDong,BangTacDong,KhoaChinh,NoiDung,DiaChiIP,ThoiGian) VALUES(1+(@i*17)%110,N'Thao tác hệ thống',N'Sach',CONVERT(NVARCHAR,@i),N'Nhật ký dữ liệu mẫu',N'10.20.1.1',DATEADD(MINUTE,-@i*43,'2026-07-25'));
 SET @i+=1;
END;
IF(SELECT COUNT(*) FROM Sach)<>310 THROW 52010,N'Sai số sách.',1; IF(SELECT COUNT(*) FROM DocGia)<>100 THROW 52011,N'Sai số độc giả.',1; IF EXISTS(SELECT 1 FROM ChiTietMuon GROUP BY MaPhieuMuon HAVING COUNT(*)>3) THROW 52012,N'Một phiếu mượn vượt quá 3 cuốn.',1; IF(SELECT COUNT(*) FROM ChiTietTra)<>480 THROW 52013,N'Sai số chi tiết trả.',1;
COMMIT; PRINT N'Đã nạp dữ liệu thành công.';
SELECT N'Sach' Bang,COUNT_BIG(*) SoDong FROM Sach UNION ALL SELECT N'DocGia',COUNT_BIG(*) FROM DocGia UNION ALL SELECT N'NhanVien',COUNT_BIG(*) FROM NhanVien UNION ALL SELECT N'CuonSach',COUNT_BIG(*) FROM CuonSach UNION ALL SELECT N'ChiTietMuon',COUNT_BIG(*) FROM ChiTietMuon UNION ALL SELECT N'DanhGiaSach',COUNT_BIG(*) FROM DanhGiaSach UNION ALL SELECT N'ThongBao',COUNT_BIG(*) FROM ThongBao;
GO
